import{_ as t,o,c as r,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Developer Monthly   December 2025   Made with Clipchamp","description":"","frontmatter":{"title":"Ceph Developer Monthly   December 2025   Made with Clipchamp","date":"2025-12-04T00:00:00.000Z","updated":"2025-12-04T00:00:00.000Z","tags":["Ceph","EC Direct Reads","Exec 操作安全性","C++/C API 安全性","兼容性","Rados API","libcephfs","BlueStore","RocksDB"],"categories":["视频总结","Ceph 社区","存储技术","软件开发","系统架构"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_Developer_Monthly_December_2025_Made_with_Clipchamp.md","filePath":"posts/2025/Ceph_Developer_Monthly_December_2025_Made_with_Clipchamp.md","lastUpdated":1780459816000}'),s={name:"posts/2025/Ceph_Developer_Monthly_December_2025_Made_with_Clipchamp.md"};function i(n,e,a,p,g,c){return o(),r("div",null,[...e[0]||(e[0]=[l('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><p>本次 Ceph 开发者月度会议主要讨论了 EC Direct Reads 的优化与 Exec 操作安全性的改进。</p><p><strong>会议要点</strong>：</p><ol><li><p><strong>EC Direct Reads 优化</strong>：</p><ul><li>目标：提升性能，客户端直接从多个 OSD 读取数据并拼接结果。</li><li>风险：Exec 操作可能因重试导致重复写入，数据损坏。</li><li>改进方向：OSD 端强化检查，明确返回错误以便调试；版本控制，避免破坏旧集群。</li></ul></li><li><p><strong>Exec 操作的安全性</strong>：</p><ul><li>现状问题：客户端可能通过标记为读的 Exec 执行写入操作。</li><li>解决方案：C++ API 改进，引入编译时安全的接口；废弃旧接口；运行时检查，OSD 对含写入的 read_op 返回错误。</li></ul></li><li><p><strong>C/C++ API 兼容性</strong>：</p><ul><li>C++ API：共识为直接移除不安全接口，维持 ABI 兼容性已无实际维护。</li><li>C API：保留现有接口，但依赖 OSD 端强制检查，避免破坏外部绑定。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>短期：提交 PR 实现 OSD 端强化检查，更新 C++ API并提供编译时安全接口。</li><li>长期：评估外部用户对 C API 的依赖，讨论 Exec 接口的公开性。</li></ul></li></ol><p><strong>其他议题</strong>：</p><ul><li>Casey 的 &quot;Fast Clones&quot; 提案：新增 RADOS 操作返回写入空间分配信息，支持 SEFS 快照克隆；RGW 对 <code>return_ve</code> 大小限制的改进需求。</li></ul><p><strong>会议结论</strong>：</p><ul><li>通过：OSD 端强制检查 + C++ API 安全改造。</li><li>搁置：完全隐藏 Exec 接口的提议。</li><li>下一步：在 dev mailing list 同步方案细节，收集社区反馈。</li></ul><h2 id="关键词保留-ceph-术语" tabindex="-1">关键词保留（Ceph 术语） <a class="header-anchor" href="#关键词保留-ceph-术语" aria-label="Permalink to &quot;关键词保留（Ceph 术语）&quot;">​</a></h2><ul><li><strong>EC (Erasure Coding)</strong> | <strong>CRUSH Algorithm</strong> | <strong>OSD/MON/MDS</strong></li><li><strong>PG (Placement Group)</strong> | <strong>RADOS</strong> | <strong>librados/libcephfs</strong></li><li><strong>Bluestore/RocksDB</strong> | <strong>Thin Provisioning</strong> | <strong>iSCSI/NFS</strong></li><li><strong>Exec Operation</strong> | <strong>C++ API</strong> | <strong>C API</strong></li><li><strong>Compatibility</strong> | <strong>Rados API</strong> | <strong>libcephfs</strong></li><li><strong>Fast Clones</strong> | <strong>SEFS</strong> | <strong>Snapshots</strong></li><li><strong>Object Class API</strong> | <strong>Exec Interface</strong> | <strong>Safety</strong></li><li><strong>Compile-time Safety</strong> | <strong>Runtime Check</strong> | <strong>Error Handling</strong></li></ul>',10)])])}const C=t(s,[["render",i]]);export{h as __pageData,C as default};
